import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputString = scanner.nextLine();
        int lengthOfString = inputString.length();

        System.out.print(inputString.charAt(0));

        boolean atFlagged = false;
        int position = 1;

        while (position < lengthOfString) {
            if (inputString.charAt(position) == 'a' && !atFlagged && checkAtSequence(inputString, position, lengthOfString)) {
                System.out.print('@');
                atFlagged = true;
                position += 2;
                continue;
            }

            if (inputString.charAt(position) == 'd' && checkDotSequence(inputString, position, lengthOfString)) {
                System.out.print('.');
                position += 3;
                continue;
            }

            System.out.print(inputString.charAt(position));
            position++;
        }
        scanner.close();
    }

    private static boolean checkDotSequence(String inputString, int position, int lengthOfString) {
        return (position + 2) < (lengthOfString - 1) && inputString.charAt(position + 1) == 'o' && inputString.charAt(position + 2) == 't';
    }

    private static boolean checkAtSequence(String inputString, int position, int lengthOfString) {
        return (position + 1) < lengthOfString && inputString.charAt(position + 1) == 't';
    }
}
